
local ofw=[==[]==]
local ewna=
(function(...)
local yuiz={79,173,201,222,190,80,212,209,106,4,191,76,45,216,1,145,60,151,154,222,70,24,29,161,166,22,50,192,240,112}
local zss=bit32 or bit
local qxifz=zss.bxor
for ptz=1,#yuiz do yuiz[ptz]=qxifz(yuiz[ptz],(149*ptz+210)%256) end
local qbk="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local lva={}
for pfjbl=1,#qbk do lva[qbk:byte(pfjbl)]=pfjbl-1 end
local function jelq(str)
  local R={} local acc,nb=0,0
  for pg=1,#str do
    local v=lva[str:byte(pg)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function fvy(key,data)
  local S={} for xvb=0,255 do S[xvb]=xvb end
  local j=0
  for taa=0,255 do
    j=(j+S[taa]+key[(taa%#key)+1])%256
    S[taa],S[j]=S[j],S[taa]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(qxifz(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=fvy(yuiz,jelq(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local zlt=nf()
return function(big) return zlt(big) end
end)(...)

return ewna(ofw)
